# --- 서블릿 필터 목록 ---

@SpringBootTest(webEnvironment = RANDOM_PORT)
class ServletFilterTest {
    @Autowired ServletContext servletContext;

    @Test
    void servletFilters() {
        servletContext.getFilterRegistrations()
                .forEach((name, reg) ->
                        System.out.println(name + " -> " + reg.getClassName()));
    }
}

$ ./gradlew test --tests ServletFilterTest

characterEncodingFilter -> org.springframework.boot.web.servlet.filter.OrderedCharacterEncodingFilter
formContentFilter -> org.springframework.boot.web.servlet.filter.OrderedFormContentFilter
requestContextFilter -> org.springframework.boot.web.servlet.filter.OrderedRequestContextFilter
springSecurityFilterChain -> org.springframework.web.filter.DelegatingFilterProxy

#   시큐리티는 하나다

#   열다섯이 아니라 하나

#   그 하나가 DelegatingFilterProxy 다

# --- 그 안에 뭐가 있나 ---

@Test
void whatIsInside() throws Exception {
    FilterRegistration reg =
            servletContext.getFilterRegistration("springSecurityFilterChain");
    System.out.println(">>> servlet filter: " + reg.getClassName());

    Filter bean = context.getBean("springSecurityFilterChain", Filter.class);
    System.out.println(">>> spring bean:    " + bean.getClass().getName());
}

>>> servlet filter: org.springframework.web.filter.DelegatingFilterProxy
