@Test
void byName() {
    boolean byType = context.getBeanNamesForType(FilterChainProxy.class).length > 0;
    boolean byName = context.containsBean("springSecurityFilterChain");

    System.out.println(">>> by type: " + byType);
    System.out.println(">>> by name: " + byName);
}

